import Database from "better-sqlite3";
import { type BetterSQLite3Database, drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import * as schema from "./schema";

export type Db = BetterSQLite3Database<typeof schema>;

export interface OpenDatabaseOptions {
	/** Path to the SQLite file, or ":memory:". */
	file: string;
	/** Folder with the SQL migrations generated by drizzle-kit. */
	migrationsFolder: string;
}

/** Opens the database and applies any pending migrations. */
export function openDatabase({ file, migrationsFolder }: OpenDatabaseOptions) {
	const sqlite = new Database(file);
	sqlite.pragma("journal_mode = WAL");
	sqlite.pragma("foreign_keys = ON");
	sqlite.pragma("busy_timeout = 5000");

	const db: Db = drizzle({ client: sqlite, schema, casing: "snake_case" });
	migrate(db, { migrationsFolder });

	return {
		db,
		/** Online backup to another file; safe while the app is using the database. */
		backup: (destination: string) => sqlite.backup(destination),
		close: () => sqlite.close(),
	};
}

export type OpenedDatabase = ReturnType<typeof openDatabase>;
